const base = ($env.CASTUO_API_URL || 'http://api:8000').replace(/\/$/, '');
const url = `${base}/health`;
const trl = ($env.TRL_LEVEL || 'TRL-6-staging').trim();
const res = await fetch(url, { method: 'GET' });
const text = await res.text();
return [{
  json: {
    trl_level: trl,
    health_url: url,
    http_status: res.status,
    ok: res.ok,
    body_preview: String(text).slice(0, 500),
    ethics_notice: 'Monitoreo técnico; sin datos personales; ver agrotech/ETHICS_TRACEABILITY.md',
    checked_at: new Date().toISOString(),
  },
}];
